    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    K = int(data[1])
    Q = int(data[2])
    A = list(map(int, data[3:3+Q]))

    # Initialize the score changes for each player
    score_changes = [0] * (N + 1)

    # Calculate the net change in score for each player
    for answer in A:
